 "info": [
  {
   "field": "customer_name",
   "about": "The customer's full name, used to look up their record. The lookup is case sensitive. An email or user id also works.",
   "from": "customer",
   "ask": "Could I have your full name so I can find your account?",
   "may_hold_back": false
  },
  {
   "field": "verification_values",
   "about": "Any 2 of: date of birth, email, phone number, address. They must match the record exactly.",
   "from": "customer",
   "ask": "To verify your identity, please give me two of these: your date of birth, email, phone number or address on file.",
   "may_hold_back": true
  },
  {
   "field": "user_id",
   "about": "The customer's internal user id, from the lookup result.",
   "from": "records",
   "ask": null,
   "may_hold_back": false
  },
  {
   "field": "credit_card_accounts",
   "about": "The customer's card accounts, each with its card type and opening date (needed for promotion windows). A customer may hold several cards, for example a business card and a personal card. Review every one.",
   "from": "records",
   "ask": null,
   "may_hold_back": false
  },
  {
   "field": "transactions",
   "about": "Each transaction's id, card type, merchant, amount, category, date and rewards earned (stored as 'X points').",
