 "steps": [
  {
   "id": "greet",
   "by": "model",
   "do": "Greet the customer politely and ask how you can help. Ask for their name (or email) and for two of: date of birth, email, phone number, address.",
   "call": null,
   "args": {},
   "lookup": [],
   "after": [],
   "if": null,
   "quote": "Be polite and professional",
   "doc": "policy"
  },
  {
   "id": "lookup_user",
   "by": "harness",
   "do": "Look up the customer's record by the name they gave. If they gave an email instead, use get_user_information_by_email. If they gave a user id, use get_user_information_by_id.",
   "call": "get_user_information_by_name",
   "args": {
    "customer_name": "the name the customer gave"
   },
   "lookup": [],
   "after": [
    "greet"
   ],
   "if": null,
   "quote": "To verify the identity of the user, call the appropriate read tools, and ensure that they are able to give correctly any 2 out of the following values: date of birth, email, phone number, address.",
   "doc": "policy"
  },
  {
   "id": "verify",
   "by": "model",
   "do": "Check that 2 of the values the customer gave (date of birth, email, phone, address) match the record from lookup_user. Reveal nothing from the record until they match. If they do not match, ask again, and do not continue until 2 values match.",
   "call": null,
   "args": {},
   "lookup": [
    "lookup_user"
   ],
   "after": [
    "lookup_user"
   ],
   "if": null,
   "quote": "Knowing full name or userID is not enough to verify.",
   "doc": "policy"
  },
  {
   "id": "get_time",
   "by": "harness",
   "do": "Get the current timestamp. Use it for the verification log and to check promotion windows.",
   "call": "get_current_time",
   "args": {},
   "lookup": [],
   "after": [
    "verify"
   ],
   "if": "verification succeeded",
   "quote": "If you need the current time, always use the get_current_time() tool.",
   "doc": "policy"
  },
  {
   "id": "log_verification",
   "by": "harness",
   "do": "Log the verification record.",
   "call": "log_verification",
   "args": {
    "name": "the verified user's name",
    "user_id": "the verified user's id",
    "address": "the address from the record",
    "email": "the email from the record",
    "phone_number": "the phone number from the record",
    "date_of_birth": "the date of birth from the record",
    "time_verified": "the timestamp from get_time"
   },
   "lookup": [],
   "after": [
    "get_time"
   ],
   "if": "verification succeeded",
   "quote": "After verification, you must call the verification logging tool to properly log the information into the verification records.",
   "doc": "policy"
  },
  {
   "id": "ask_scope",
   "by": "model",
   "do": "Ask which purchases or cards look wrong. If the customer cannot say (for example, they do not have their statements or cannot use online tools), tell them you will review every transaction on every card they hold. Do not ask for receipts or card numbers.",
   "call": null,
   "args": {},
   "lookup": [],
   "after": [
    "log_verification"
   ],
   "if": "the customer has not said which transactions they think are wrong",
   "quote": "Our customer service team has the tools to investigate cash back discrepancies and review your transaction history.",
   "doc": "doc_credit_cards_credit_cards_(general)_021"
  },
  {
   "id": "get_accounts",
   "by": "harness",
   "do": "Get the customer's credit card accounts, with each card's type and opening date.",
   "call": "get_credit_card_accounts_by_user",
   "args": {
    "user_id": "the verified user's id"
   },
   "lookup": [],
   "after": [
    "log_verification"
   ],
   "if": null,
   "quote": "Recalculate the correct rewards for each transaction based on the card type, transaction category, and any applicable promotions.",
   "doc": "doc_credit_cards_credit_cards_(general)_004"
  },
  {
   "id": "get_transactions",
   "by": "harness",
   "do": "Get all of the customer's credit card transactions.",
   "call": "get_credit_card_transactions_by_user",
   "args": {
    "user_id": "the verified user's id"
   },
   "lookup": [],
   "after": [
    "log_verification"
   ],
   "if": null,
   "quote": "Our customer service team has the tools to investigate cash back discrepancies and review your transaction history.",
   "doc": "doc_credit_cards_credit_cards_(general)_021"
  },
  {
   "id": "explain_card_rates",
   "by": "model",
   "do": "If the customer does not know their cards' rates, explain the rates of each card they hold (from get_accounts), using the rate rules below. Explain that the records store all rewards as points: on cash back cards 1 point = $0.01, and the EcoCard earns sustainability points (5 per dollar on green purchases, 1 per dollar otherwise).",
   "call": null,
   "args": {},
   "lookup": [
    "get_accounts"
   ],
   "after": [
    "get_accounts"
   ],
   "if": "the customer is unsure of or asks about their cards' cash back or points rates",
   "quote": "all credit card rewards in the transaction database are stored as 'points' regardless of whether the card is a cash back card or a points-based card.",
   "doc": "doc_credit_cards_credit_cards_(general)_006"
  },
  {
   "id": "check_business_silver_promo",
   "by": "model",
   "do": "For each Business Silver Rewards Card account (from get_accounts), decide whether the double cash back promo applies:\n1. The account opening date must be between 2024-11-14 and 2025-11-14.\n2. The promo then covers only transactions dated within 6 months after that opening date.\n3. On those transactions, double the rate: 10.0% becomes 20.0%, and 1.0% becomes 2.0%.\n4. Excluded merchants still earn only the standard 1.0%, doubled within the window.\nEvery other Business Silver transaction uses the standard rates.",
   "call": null,
   "args": {},
   "lookup": [
    "get_accounts",
    "get_transactions"
   ],
   "after": [
    "get_accounts",
    "get_transactions"
   ],
   "if": "the customer holds a Business Silver Rewards Card",
   "quote": "The 6-month window begins on your account opening date, not the promotional start date",
   "doc": "doc_business_credit_cards_business_silver_rewards_card_012"
  },
  {
   "id": "check_silver_rewards",
   "by": "model",
   "do": "For each Silver Rewards Card (personal) transaction (card type from get_accounts or the transaction record):\n1. Travel or software category: 4.0%.\n2. Parking, tolls and local transit earn 4.0% only when the merchant is classified as travel.\n3. Hardware, telecom or internet charges are not software.\n4. Gift cards, person-to-person payments, bank fees, interest and insurance premiums do not earn the bonus rate.\n5. Everything else: 1.0%.\nNo rewards-rate multiplier promotion is documented for this card, so apply no promo multiplier. Use the result in recalculate.",
   "call": null,
   "args": {},
   "lookup": [
    "get_accounts",
    "get_transactions"
   ],
   "after": [
    "get_accounts",
    "get_transactions"
   ],
   "if": "the customer holds a Silver Rewards Card",
   "quote": "Pay with your card for eligible travel and software transactions to earn 4.0% back",
   "doc": "doc_credit_cards_silver_rewards_card_002"
  },
  {
   "id": "check_business_bronze_exclusions",
   "by": "model",
   "do": "For each Business Bronze Rewards Card transaction (card type from get_accounts or the transaction record):\n1. WeWork, Regus, Industrious (coworking) and Gusto, ADP, Paychex, Rippling (payroll): correct points = 0.\n2. Slack, Zoom, HubSpot, Salesforce: find the earliest charge to that merchant on that card in get_transactions. Charges within 12 months of it earn 1.0%. Later charges (auto-renewals, continued payments) earn 0.\n3. All other merchants earn 1.0% on the net amount after credits or returns.",
   "call": null,
   "args": {},
   "lookup": [
    "get_accounts",
    "get_transactions"
   ],
   "after": [
    "get_accounts",
    "get_transactions"
   ],
   "if": "the customer holds a Business Bronze Rewards Card",
   "quote": "The following SaaS merchants earn the 1.0% rate for the first 12 months of your subscription only.",
   "doc": "doc_business_credit_cards_business_bronze_rewards_card_003"
  },
  {
   "id": "recalculate",
   "by": "model",
   "do": "Work out the correct points for each transaction, on every card the customer holds:\n1. Take the card's rate for the transaction's category from the rules. That means the bonus category rate or the base rate, any merchant exclusion, and any promotion active for the account on the purchase date. For Business Silver use check_business_silver_promo. For Silver Rewards use check_silver_rewards. For Business Bronze use check_business_bronze_exclusions. For the EcoCard, apply the Target/Walmart/Amazon/ThredUp exclusions and the EV-network rule.\n2. Multiply the amount by that rate. A rate of 1% earns 1 point per dollar.\n3. Round down to a whole number.\nCompare the result with the recorded rewards, and list every transaction whose recorded points differ, in either direction. Never use any expected_rewards field or the customer's expectation. Work only from the rate rules.",
   "call": null,
   "args": {},
   "lookup": [
    "get_accounts",
    "get_transactions",
    "get_time",
    "check_business_silver_promo",
    "check_silver_rewards",
    "check_business_bronze_exclusions"
   ],
   "after": [
    "get_accounts",
    "get_transactions"
   ],
   "if": null,
   "quote": "Ensure your calculation reflects the proper base rate and any active bonus category or promotion at the time of purchase.",
   "doc": "doc_credit_cards_credit_cards_(general)_004"
  },
  {
   "id": "classify_transactions",
   "by": "model",
   "do": "Sort each transaction that differs into one of two groups:\n- underpaid: the recorded points are lower than the correct points.\n- overpaid: the recorded points are higher than the correct points.",
   "call": null,
   "args": {},
   "lookup": [
    "get_transactions",
    "recalculate"
   ],
   "after": [
    "recalculate"
   ],
   "if": null,
   "quote": "The cash back amount seems lower than what you calculated based on your card's rates",
   "doc": "doc_credit_cards_credit_cards_(general)_021"
  },
  {
   "id": "explain_findings",
   "by": "model",
   "do": "Tell the customer which transactions (id, merchant, amount, card) received the wrong rewards. For each one, give the points received, the correct points (1 point = $0.01), and whether it was too high or too low. If there is no discrepancy, say so plainly.",
   "call": null,
   "args": {},
   "lookup": [
    "classify_transactions"
   ],
   "after": [
    "classify_transactions"
   ],
   "if": null,
   "quote": "we'll look into the specific transaction, verify the merchant category, check the applicable reward rates for your card, and determine if an adjustment is needed.",
   "doc": "doc_credit_cards_credit_cards_(general)_021"
  },
  {
   "id": "explain_legitimate_exceptions",
   "by": "model",
   "do": "Some transactions have recorded rewards below the card's usual rate but equal to the correct points, because of a documented merchant exclusion. Tell the customer each of these is correct, and why. Examples: Business Bronze coworking and payroll merchants, and SaaS renewals after 12 months, earn 0%. On the EcoCard, purchases at Target, Walmart, Amazon or ThredUp, and EV charging off the Tesla Supercharger/ChargePoint/EVgo networks, earn 1 point per dollar. Do not offer a dispute for these.",
   "call": null,
   "args": {},
   "lookup": [
    "recalculate",
    "get_transactions"
   ],
   "after": [
    "explain_findings"
   ],
   "if": "at least one transaction earned a reduced rate because of a documented merchant exclusion",
   "quote": "The following specific merchants do NOT earn the higher sustainability points rate ($5.00 points per dollar) and instead earn the standard rate ($1.00 point per dollar):",
   "doc": "doc_credit_cards_ecocard_004"
  },
  {
   "id": "handle_overpaid",
   "by": "model",
   "do": "For each overpaid transaction:\n1. Tell the customer it earned more than its rate gives, with the recorded and the correct points.\n2. Ask whether they want it corrected. Never lower its rewards yourself.\n3. If they want it corrected, add its transaction_id to the transactions they will dispute with submit_cash_back_dispute_0589 (give_dispute_tool, instruct_customer).\n4. If they do not, leave it as it is and do not dispute it.",
   "call": null,
   "args": {},
   "lookup": [
    "classify_transactions"
   ],
   "after": [
    "explain_findings"
   ],
   "if": "at least one transaction is overpaid",
   "quote": "Use this process when a customer believes there is a discrepancy between the cash back they received for a particular transaction and the cash back they should have received.",
   "doc": "doc_credit_cards_credit_cards_(general)_003"
  },
  {
   "id": "no_discrepancy",
   "by": "model",
   "do": "Tell the customer that none of their transactions needs a dispute: none earned less than their cards' rates give, and they do not want any overpaid transaction corrected. Do not give the dispute tool. Close the request.",
   "call": null,
   "args": {},
   "lookup": [
    "classify_transactions",
    "handle_overpaid"
   ],
   "after": [
    "explain_findings"
   ],
   "if": "no transaction is underpaid, and the customer has not asked for any overpaid transaction to be corrected",
   "quote": "When you contact us, we'll look into the specific transaction, verify the merchant category, check the applicable reward rates for your card, and determine if an adjustment is needed.",
   "doc": "doc_credit_cards_credit_cards_(general)_021"
  },
  {
   "id": "give_dispute_tool",
   "by": "harness",
   "do": "Give the customer the cash back dispute tool, once.",
   "call": "give_discoverable_user_tool",
   "args": {
    "discoverable_tool_name": "submit_cash_back_dispute_0589"
   },
   "lookup": [
    "classify_transactions",
    "handle_overpaid"
   ],
   "after": [
    "explain_findings"
   ],
   "if": "at least one transaction is underpaid (recorded points lower than the correct points), or the customer asked for at least one overpaid transaction to be corrected",
   "quote": "Tool to provide to the user: `submit_cash_back_dispute_0589(user_id: str, transaction_id: str)`",
   "doc": "doc_credit_cards_credit_cards_(general)_003"
  },
  {
   "id": "instruct_customer",
   "by": "model",
   "do": "Give the customer their user_id and the exact transaction_id of each transaction to dispute: every underpaid transaction, plus each overpaid one they asked to have corrected. Confirm the ids are correct. Tell them to run the tool once per transaction, on every card. Do not ask for card details. Mention that supporting context may be requested later in the review.",
   "call": null,
   "args": {
    "user_id": "the verified user's id",
    "transaction_id": "each underpaid transaction from classify_transactions, plus each overpaid transaction the customer asked to correct in handle_overpaid"
   },
   "lookup": [
    "classify_transactions",
    "handle_overpaid"
   ],
   "after": [
    "give_dispute_tool"
   ],
   "if": "the dispute tool was given",
   "quote": "Tell the customer to run the tool with their own user_id and the specific transaction_id for the purchase in question.",
   "doc": "doc_credit_cards_credit_cards_(general)_003"
  },
  {
   "id": "customer_asks_agent_to_file",
   "by": "model",
   "do": "If the customer asks you to file the disputes for them (for example, because they are not comfortable with technology), explain politely that this dispute is submitted with the tool you gave them. Walk them through each call, one transaction at a time, giving the exact user_id and transaction_id to enter. Do not submit it yourself.",
   "call": null,
   "args": {},
   "lookup": [
    "instruct_customer"
   ],
   "after": [
    "instruct_customer"
   ],
   "if": "the customer asks the agent to submit the disputes on their behalf",
   "quote": "Instead of a step-by-step workflow, instruct the customer to use the tool directly:",
   "doc": "doc_credit_cards_credit_cards_(general)_003"
  },
  {
   "id": "customer_submits",
   "by": "customer",
   "do": "The customer runs submit_cash_back_dispute_0589 through call_discoverable_user_tool, once for each transaction to dispute: every underpaid transaction, and each overpaid one they chose to correct.",
   "call": "submit_cash_back_dispute_0589",
   "args": {
    "user_id": "the verified user's id",
    "transaction_id": "each transaction id listed in instruct_customer"
   },
   "lookup": [],
   "after": [
    "instruct_customer"
   ],
   "if": null,
   "quote": "Confirm the customer has the correct transaction_id before they submit.",
   "doc": "doc_credit_cards_credit_cards_(general)_003"
  },
  {
   "id": "advise_review",
   "by": "model",
   "do": "Tell the customer the disputes are now under review and that supporting context, such as category or promotion expectations, may be requested later. Rewards are corrected only after a dispute is resolved and approved; if the customer then asks for an update, follow applying_resolved_cash_back_dispute_corrections.",
   "call": null,
   "args": {},
   "lookup": [],
   "after": [
    "customer_submits"
   ],
   "if": "a dispute was submitted",
   "quote": "Advise the customer that supporting context (e.g., category or promotion expectations) may be requested later during review, but the submission itself is initiated with the tool above.",
   "doc": "doc_credit_cards_credit_cards_(general)_003"
  },
  {
   "id": "handle_errors",
   "by": "model",
   "do": "If a read tool or the customer's submission returns an error:\n1. Retry once with the corrected user_id or transaction_id.\n2. If it still fails, explain the problem and ask whether the customer wants a human agent.\n3. Call transfer_to_human_agents only if they say yes.",
   "call": "transfer_to_human_agents",
   "args": {
    "summary": "what was found and what failed",
    "reason": "the error returned"
   },
   "lookup": [],
   "after": [
    "get_transactions"
   ],
   "if": "a call returns an error that a retry does not fix and the customer agrees to a transfer",
   "quote": "If they do, invoke the appropriate transfer_to_human_agents tool.",
   "doc": "policy"
  }
 ],
 "rules": [
  {
   "rule": "Verify identity with 2 matching values out of DOB, email, phone and address before revealing or using any account data. A name or user id alone does not verify.",
   "quote": "Knowing full name or userID is not enough to verify.",
   "doc": "policy"
  },
  {
   "rule": "The database stores all rewards as points. On cash back cards, 1 point = $0.01, so a rate of R% earns R points per dollar.",
   "quote": "For example, 250 points equals $2.50 in cash back, which matches a 2.5% cash back rate on a $100 purchase.",
   "doc": "doc_credit_cards_credit_cards_(general)_006"
  },
  {
   "rule": "EcoCard earns 5 points per dollar on green purchases and 1 point per dollar on all others.",
   "quote": "5 points per dollar on green purchases, 1 point per dollar on other purchases",
   "doc": "doc_credit_cards_credit_cards_(general)_006"
  },
  {
   "rule": "Always round points down to a whole number (floor).",
   "quote": "All credit card rewards points are rounded down to the nearest whole number.",
   "doc": "doc_credit_cards_credit_cards_(general)_007"
  },
  {
   "rule": "Bronze Rewards Card: 1.0% on all eligible purchases.",
   "quote": "You earn 1.0% cash back on eligible purchases.",
   "doc": "doc_credit_cards_bronze_rewards_card_002"
  },
  {
   "rule": "Silver Rewards Card: 4.0% on travel and software, 1.0% on everything else.",
   "quote": "Pay with your card for eligible travel and software transactions to earn 4.0% back",
   "doc": "doc_credit_cards_silver_rewards_card_002"
  },
  {
   "rule": "Silver Rewards Card base rate is 1.0%.",
   "quote": "Purchases outside top categories earn 1.0% back",
   "doc": "doc_credit_cards_silver_rewards_card_001"
  },
  {
   "rule": "Silver Rewards Card: gift cards, person-to-person payments, bank fees, interest and insurance premiums do not earn the 4.0% bonus rate.",
   "quote": "Gift cards, person-to-person payments, fees, interest, and insurance premiums charged by the bank",
   "doc": "doc_credit_cards_silver_rewards_card_002"
  },
  {
   "rule": "Silver Rewards Card: parking, tolls and local transit earn 4.0% only when the merchant is classified as travel.",
   "quote": "Parking garages, tolls, or local transit if the merchant is not classified as travel",
   "doc": "doc_credit_cards_silver_rewards_card_003"
  },
  {
   "rule": "Silver Rewards Card: hardware sold by tech retailers is not software and earns 1.0%.",
   "quote": "Hardware devices, peripherals, or equipment sold by tech retailers",
   "doc": "doc_credit_cards_silver_rewards_card_004"
  },
  {
   "rule": "Gold Rewards Card: 2.5% on all purchases.",
   "quote": "Earn 2.5% cash back on all purchases.",
   "doc": "doc_credit_cards_gold_rewards_card_005"
  },
  {
   "rule": "The Gold Rewards Card terms page also gives 2.5% on all purchases, with no bonus categories, so expected points = floor(amount × 2.5).",
   "quote": "Cash back on all purchases: 2.5%",
   "doc": "doc_credit_cards_gold_rewards_card_001"
